        let formattedDate = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(now.getDate()).padStart(2, '0');
        save(formattedDate + '.png'); // Save canvas as PNG with the current date as the filename
    }
}




// === Tab: shader.frag ===
#ifdef GL_ES
precision highp float;
#endif

uniform vec2 iResolution;
uniform float iTime;
varying vec2 vTexCoord;

float TAU = 2.0*3.14159256;

vec3 random3(vec3 c) {
    float j = 4096.0*sin(dot(c,vec3(17.0, 59.4, 15.0)));
    vec3 r;
    r.z = fract(512.0*j);
    j *= .125;
    r.x = fract(512.0*j);
    j *= .125;
    r.y = fract(512.0*j);
    return r-0.5;
}

const float F3 =  0.3333333;
const float G3 =  0.1666667;

float simplex3d(vec3 p) {
    vec3 s = floor(p + dot(p, vec3(F3)));
    vec3 x = p - s + dot(s, vec3(G3));

    vec3 e = step(vec3(0.0), x - x.yzx);
    vec3 i1 = e*(1.0 - e.zxy);
    vec3 i2 = 1.0 - e.zxy*(1.0 - e);

    vec3 x1 = x - i1 + G3;
    vec3 x2 = x - i2 + 2.0*G3;
    vec3 x3 = x - 1.0 + 3.0*G3;

    vec4 w, d;
    w.x = dot(x, x);
    w.y = dot(x1, x1);
    w.z = dot(x2, x2);
    w.w = dot(x3, x3);

    w = max(0.6 - w, 0.0);

    d.x = dot(random3(s), x);
    d.y = dot(random3(s + i1), x1);
    d.z = dot(random3(s + i2), x2);
    d.w = dot(random3(s + 1.0), x3);

    w *= w;
    w *= w;
    d *= w;

    return dot(d, vec4(52.0));
}

vec3 palette( float t ) {
    vec3 a = vec3(0.9, 0.5, 0.2);
    vec3 b = vec3(0.8, 0.1, 0.0);
    vec3 c = vec3(1.5, 1.2, 0.8);
    vec3 d = vec3(0.7, 0.9, 0.1);

    vec3 riverColor = vec3(0.2, 0.5, 0.7);
    float riverFactor = smoothstep(-0.1, 0.1, vTexCoord.y - 0.5);

    return mix(a + b * cos(6.28318 * (c * t + d)), riverColor, riverFactor);
}

float polygonSDF(vec2 p, float sides, float radius) {
    float angle = TAU / sides;
    float a = atan(p.y, p.x);
    float r = length(p);
    float h = abs(mod(a, angle) - angle * 0.5);
    return (radius - r * cos(h)) / length(vec2(cos(h), sin(h)));
}

void main() {
    vec2 coord = vTexCoord;
    float u = coord.x * 2.0 - 1.0;
    float v = coord.y * 2.0 - 1.0;
    const float scale = 1.21;
    u = u * scale * iResolution.x / iResolution.y;
    v = v * scale;
    vec2 uv = vec2(u, v);
    vec2 uv0 = vec2(u, v);

    vec3 col = vec3(0.0, 0.0, 0.0);

    float speed = iTime / 5.0;
    float n = simplex3d(vec3(2.0*sin(speed + uv.x * 1.0), 1.1*cos(speed + uv.y * 1.0), uv.y + uv.x));

    for(float i = 0.0; i < 10.0; i++){
        float trail = 0.03 + i * 0.005; // トレイルの広がりを追加
        float shape = polygonSDF(uv, 30.0, 0.5 - 0.05 * i) + n * n;
        vec3 colrs = palette(length(uv0) + i * 1.0 - iTime*0.3);
        col = mix(col, colrs, smoothstep(-trail, trail, shape));
    }

    gl_FragColor = vec4(col, 1.0);
}


// === Tab: shader.vert ===
#ifdef GL_ES
precision highp float;
#endif

// our vertex data
attribute vec3 aPosition;
attribute vec2 aTexCoord;

varying vec2 vTexCoord;

uniform float iTime; // 追加: 時間情報のためのuniform変数

void main() {

  vTexCoord = aTexCoord;

  vec4 positionVec4 = vec4(aPosition, 1.0);

  // 波のアニメーションの追加
  float wave = sin(positionVec4.x * 10.0 + iTime) * 0.1; 
  positionVec4.y += wave;

  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  gl_Position = positionVec4;
}

